def _extract_bhs_simple_shift_section(case_rec, books_mpu):
    verses = books_mpu[case_rec.book_id]["verses_plus"]
    anchor_bcvt = case_rec.mam_anchor_bcvt
    shifted_bcvt_seq = _shifted_bcvt_seq(case_rec, verses)
    rows = [_mk_unchanged_row(_preceding_bcvt(verses, anchor_bcvt), verses)]
    rows.append(_mk_row(anchor_bcvt, verses))
    rows.extend(
        _mk_row(shifted_bcvt, verses)
        for shifted_bcvt in shifted_bcvt_seq[: case_rec.leading_shifted_rows]
    )
    if shifted_bcvt_seq[case_rec.leading_shifted_rows : -1]:
        rows.append(SimpleShiftRowRec("", "…", "…"))
    rows.append(_mk_row(shifted_bcvt_seq[-1], verses))
    return SimpleShiftSectionRec(
        heading=case_rec.bhs_heading,
        table_separator=case_rec.bhs_table_separator,
        intro_lines=_intro_lines_for_case(case_rec),
        rows=tuple(rows),
        anchor_id=_bhs_anchor_id(case_rec),
    )


def _extract_bhs_split_one_vs_many_section(case_rec, books_mpu):
    verses = books_mpu[case_rec.book_id]["verses_plus"]
    anchor_bcvt = case_rec.mam_anchor_bcvt
    rows = [_mk_unchanged_row(_preceding_bcvt(verses, anchor_bcvt), verses)]
    rows.extend(_split_anchor_rows(case_rec, verses[anchor_bcvt]))
    shifted_chnu = tbn.bcvt_get_chnu(anchor_bcvt)
    first_shifted_bcvt = tbn.mk_bcvtmam(
        case_rec.book_id, shifted_chnu, tbn.bcvt_get_vrnu(anchor_bcvt) + 1
    )
    last_shifted_bcvt = tbn.mk_bcvtmam(
        case_rec.book_id, shifted_chnu, case_rec.last_shifted_vrnu
    )
    rows.append(_mk_row(first_shifted_bcvt, verses))
    if first_shifted_bcvt != last_shifted_bcvt:
        rows.append(SimpleShiftRowRec("", "…", "…"))
        rows.append(_mk_row(last_shifted_bcvt, verses))
    return SimpleShiftSectionRec(
        heading=case_rec.bhs_heading,
        table_separator=case_rec.bhs_table_separator,
        intro_lines=_intro_lines_for_split_one_vs_many_case(case_rec),
        rows=tuple(rows),
        note_lines=case_rec.note_lines,
        anchor_id=_bhs_anchor_id(case_rec),
    )


def _extract_bhs_complex_boundary_section(case_rec, books_mpu):
    verses = books_mpu[case_rec.book_id]["verses_plus"]
    rows = [
        _mk_unchanged_row(_preceding_bcvt(verses, case_rec.mam_anchor_bcvt), verses)
    ]
    rows.extend(_split_anchor_rows(case_rec, verses[case_rec.mam_anchor_bcvt]))
    return SimpleShiftSectionRec(
        heading=case_rec.bhs_heading,
        table_separator=case_rec.bhs_table_separator,
        intro_lines=_intro_lines_for_complex_boundary_case(case_rec),
        rows=tuple(rows),
        note_lines=case_rec.note_lines,
        anchor_id=_bhs_anchor_id(case_rec),
    )


def _extract_bhs_present_vs_absent_section(case_rec, books_mpu):
    verses = books_mpu[case_rec.book_id]["verses_plus"]
    anchor_bcvt = case_rec.mam_anchor_bcvt
    rows = [_mk_row(anchor_bcvt, verses)]
    rows.extend(_absent_rows(case_rec))
    shifted_bcvt_seq = _shifted_bcvt_seq_same_chapter(case_rec, verses)
    rows.append(_mk_row(shifted_bcvt_seq[0], verses))
    if len(shifted_bcvt_seq) > 1:
        rows.append(SimpleShiftRowRec("", "…", "…"))
        rows.append(_mk_row(shifted_bcvt_seq[-1], verses))
    return SimpleShiftSectionRec(
        heading=case_rec.bhs_heading,
        table_separator=case_rec.bhs_table_separator,
        intro_lines=_intro_lines_for_present_vs_absent_case(),
        rows=tuple(rows),
        anchor_id=_bhs_anchor_id(case_rec),
    )


def _bhs_anchor_id(case_rec):
    return f"bhs-{case_rec.case_id}"


def _shifted_bcvt_seq(case_rec, verses):
    anchor_bcvt = case_rec.mam_anchor_bcvt
    shifted_chnu = tbn.bcvt_get_chnu(anchor_bcvt) + 1
    shifted_rows = []
    for bcvt in verses:
        if tbn.bcvt_get_chnu(bcvt) != shifted_chnu:
            continue
        maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[tbn.VT_BHS].get(bcvt)
        if maprec is None:
            continue
        shifted_rows.append(bcvt)
    return tuple(shifted_rows)


def _shifted_bcvt_seq_same_chapter(case_rec, verses):
    anchor_bcvt = case_rec.mam_anchor_bcvt
    anchor_chnu = tbn.bcvt_get_chnu(anchor_bcvt)
    anchor_vrnu = tbn.bcvt_get_vrnu(anchor_bcvt)
    shifted_rows = []
    for bcvt in verses:
        if tbn.bcvt_get_chnu(bcvt) != anchor_chnu:
            continue
        if tbn.bcvt_get_vrnu(bcvt) <= anchor_vrnu:
            continue
        maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[tbn.VT_BHS].get(bcvt)
        if maprec is None:
            continue
        shifted_rows.append(bcvt)
    return tuple(shifted_rows)


def _preceding_bcvt(verses, mam_bcvt):
    verse_keys = tuple(verses)
    mam_idx = verse_keys.index(mam_bcvt)
    assert mam_idx > 0
    return verse_keys[mam_idx - 1]


def _mk_row(mam_bcvt, verses):
    return _mk_row_for_vtrad(tbn.VT_BHS, mam_bcvt, verses)


def _mk_unchanged_row(mam_bcvt, verses):
    cv_label = _cv_label(mam_bcvt)
    return SimpleShiftRowRec(
        hebrew_range=hebrew.range_label_for_minirow(verses[mam_bcvt]),
        mam_label=cv_label,
        other_label=cv_label,
    )


def _mk_row_for_vtrad(vtrad, mam_bcvt, verses):
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad][mam_bcvt]
    other_cvt, _is_empty = maprec[0]
    other_bcvt = tbn.mk_bcvt(tbn.bcvt_get_bk39id(mam_bcvt), other_cvt)
    return SimpleShiftRowRec(
        hebrew_range=hebrew.range_label_for_minirow(verses[mam_bcvt]),
        mam_label=_cv_label(mam_bcvt),
        other_label=_cv_label(other_bcvt),
    )


def _absent_rows(case_rec):
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[tbn.VT_BHS][case_rec.mam_anchor_bcvt]
    return tuple(
        SimpleShiftRowRec(
            hebrew_range="—",
            mam_label="*(absent)*",
            other_label=_cv_label(tbn.mk_bcvt(case_rec.book_id, cvve[0])),
        )
        for cvve in maprec[1:]
    )


def _split_anchor_rows(case_rec, minirow, vtrad=tbn.VT_BHS):
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad][case_rec.mam_anchor_bcvt]
    split_wtseqs = _split_anchor_wtseqs(case_rec, minirow.EP)
    anchor_label = _cv_label(case_rec.mam_anchor_bcvt)
    return tuple(
        SimpleShiftRowRec(
            hebrew_range=_split_row_label(case_rec, split_wtseq, idx),
            mam_label=anchor_label + suffix,
            other_label=_cv_label(tbn.mk_bcvt(case_rec.book_id, cvve[0])),
        )
        for idx, (suffix, split_wtseq, cvve) in enumerate(
            zip(case_rec.split_part_suffixes, split_wtseqs, maprec)
        )
    )


def _split_row_label(case_rec, split_wtseq, idx):
    if len(case_rec.split_part_suffixes) == 4 and idx < 3:
        return hebrew.first_two_word_label_for_wtseq(split_wtseq)
    return hebrew.range_label_for_wtseq(split_wtseq)


def _split_anchor_wtseqs(case_rec, ep_wtseq):
    if case_rec.renderer_kind == case_data.RENDERER_KIND_COMPLEX_BOUNDARY:
        assert len(ep_wtseq) == 3
        return ((ep_wtseq[0],), (ep_wtseq[2],))
    return _split_decalogue_anchor_wtseqs(ep_wtseq)


def _split_decalogue_anchor_wtseqs(ep_wtseq):
    if len(ep_wtseq) == 3:
        assert ep_wtseq[1] == " "
        return ((ep_wtseq[0],), (ep_wtseq[2],))
    assert len(ep_wtseq) == 7
    return (
        (ep_wtseq[0],),
        (ep_wtseq[2],),
        (ep_wtseq[4],),
        (ep_wtseq[6],),
    )


def _cv_label(bcvt):
    return f"{tbn.bcvt_get_chnu(bcvt)}:{tbn.bcvt_get_vrnu(bcvt)}"


def _intro_lines_for_case(case_rec):
    anchor_bcvt = case_rec.mam_anchor_bcvt
    anchor_label = _cv_label(anchor_bcvt)
    anchor_bhs_cvt, _is_empty = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[tbn.VT_BHS][
        anchor_bcvt
    ][0]
    anchor_bhs_bcvt = tbn.mk_bcvt(case_rec.book_id, anchor_bhs_cvt)
    shifted_chnu = tbn.bcvt_get_chnu(anchor_bcvt) + 1
    return (
        "The span of text labeled "
        + anchor_label
        + " in MAM is labeled "
        + _cv_label(anchor_bhs_bcvt)
        + " in BHS.",
        "Then MAM's verse numbers are one lower than BHS's for the rest of chapter "
        + str(shifted_chnu)
        + ".",
    )


def _intro_lines_for_split_one_vs_many_case(case_rec):
    anchor_label = _cv_label(case_rec.mam_anchor_bcvt)
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[tbn.VT_BHS][case_rec.mam_anchor_bcvt]
    bhs_labels = tuple(
        _cv_label(tbn.mk_bcvt(case_rec.book_id, cvve[0])) for cvve in maprec
    )
    return (
        "The span of text labeled " + anchor_label + " in MAM",
        "is labeled as " + _join_labels_with_and(bhs_labels) + " in BHS.",
    )


