def _intro_lines_for_present_vs_absent_case():
    return (
        "BHS inserts verses 36 and 37 at a point where MAM has no",
        "corresponding Hebrew text (these verses are absent from the Aleppo Codex and",
        "the Leningrad Codex). In the MAM output that needs to have BHS versification,",
        "those two verse elements are present but have only a dash (—) as their text",
        'and they are marked `contents-corresponds-to="no verse in MAM"`.',
    )


def _intro_lines_for_sef_early_one_vs_many_case(case_rec):
    anchor_label = _cv_label(case_rec.mam_anchor_bcvt)
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[tbn.VT_SEF][case_rec.mam_anchor_bcvt]
    sef_labels = tuple(
        _cv_label(tbn.mk_bcvt(case_rec.book_id, cvve[0])) for cvve in maprec
    )
    contrast_label = _cv_label(case_rec.sef_contrast_anchor_bcvt)
    early_bhs_anchor = _bhs_anchor_id(case_rec)
    late_bhs_anchor = _late_decalogue_bhs_anchor_id(case_rec)
    return (
        f"As in [BHS](#{early_bhs_anchor}), the span of text labeled "
        + anchor_label
        + " in MAM",
        "is labeled as "
        + _join_labels_with_and(sef_labels)
        + " in Sef. Unlike [BHS](#"
        + late_bhs_anchor
        + "), Sef does not go on to split the span of text labeled "
        + contrast_label
        + " in MAM.",
    )


def _late_decalogue_bhs_anchor_id(case_rec):
    if case_rec.book_id == tbn.BK_EXODUS:
        return "bhs-exod-20-late-decalogue"
    assert case_rec.book_id == tbn.BK_DEUTER
    return "bhs-deut-5-late-decalogue"


def _last_shifted_bcvt_in_chapter(vtrad, start_bcvt, verses):
    start_chnu = tbn.bcvt_get_chnu(start_bcvt)
    start_vrnu = tbn.bcvt_get_vrnu(start_bcvt)
    candidates = []
    for bcvt in verses:
        if tbn.bcvt_get_chnu(bcvt) != start_chnu:
            continue
        if tbn.bcvt_get_vrnu(bcvt) < start_vrnu:
            continue
        if vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad].get(bcvt) is None:
            continue
        candidates.append(bcvt)
    return candidates[-1]


def _join_labels_with_and(labels):
    assert len(labels) >= 2
    compact_range = _compact_consecutive_label_range(labels)
    if compact_range is not None:
        return compact_range
    if len(labels) == 2:
        return labels[0] + " and " + labels[1]
    return ", ".join(labels[:-1]) + ", and " + labels[-1]


def _compact_consecutive_label_range(labels):
    if len(labels) < 3:
        return None
    chapter_strs = []
    verse_nums = []
    for label in labels:
        chapter_str, sep, verse_str = label.partition(":")
        if sep != ":" or not chapter_str.isdigit() or not verse_str.isdigit():
            return None
        chapter_strs.append(chapter_str)
        verse_nums.append(int(verse_str))
    if len(set(chapter_strs)) != 1:
        return None
    expected = list(range(verse_nums[0], verse_nums[0] + len(verse_nums)))
    if verse_nums != expected:
        return None
    return f"{chapter_strs[0]}:{verse_nums[0]}–{verse_nums[-1]}"
